run(function()
	local Velocity
	local Vertical
	local Horizontal
	local Mode
	local DelayGround
	local DelayAir
	local Targetting
	local Chance
	local KiteMode
	local KiteHorizontal
	local KiteVertical
	local AlwaysKite
	local old = nil
	local rand = Random.new()

	local function hitterPosition(hitFrom)
		local ok, ids = pcall(function()
			return bedwars.KnockbackController.recentlyReceivedKnockback:getValues()
		end)
		if ok and type(ids) == 'table' then
			for i = #ids, 1, -1 do
				local plr = playersService:GetPlayerByUserId(ids[i])
				local char = plr and plr.Character
				local part = char and char.PrimaryPart
				if part then
					return part.Position
				end
			end
		end
		return typeof(hitFrom) == 'Vector3' and hitFrom or nil
	end

	local function kiting(root, hitFrom)
		if not KiteMode.Enabled then return false end
		if AlwaysKite.Enabled then return true end
		if not root then return false end
		local from = hitterPosition(hitFrom)
		if not from or (from - root.Position).Magnitude > 20 then return false end
		local toHitter = (from - root.Position) * Vector3.new(1, 0, 1)
		local look = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		if toHitter.Magnitude < 0.5 or look.Magnitude < 0.01 then return false end
		return look.Unit:Dot(toHitter.Unit) < -0.2
	end

	Velocity = vape.Categories.Combat:CreateModule({
		Name = 'Velocity',
		Tooltip = 'control you to edit ur knockback',
		Function = function(callback)
			if callback then
				old = bedwars.KnockbackUtil.applyKnockback
				Velocity:Clean(vapeEvents.TakeKnockback.Event:Connect(function(root, mass, dir, knockback, ...)
					local args = {...}
					local clone = table.clone(knockback)

					local air, ground = false, false
					task.delay(DelayAir.Value / 1000, function()
						clone.horizontal = knockback.horizontal or 1
						air = true
					end)
					task.delay(DelayGround.Value / 1000, function()
						clone.vertical = knockback.vertical or 1
						ground = true
					end)
					repeat task.wait(0.1) until air
					repeat task.wait(0.05) until ground
					old(root, mass, dir, clone, unpack(args))
				end))

				bedwars.KnockbackUtil.applyKnockback = function(root, mass, dir, knockback, ...)
					local check = (not Targetting.Enabled) or entitylib.EntityPosition({
						Range = 50,
						Part = 'RootPart',
						Players = true
					})

					if check and kiting(root, dir) then
						local boosted = table.clone(knockback or {})
						boosted.horizontal = (boosted.horizontal or 1) * (KiteHorizontal.Value / 100)
						boosted.vertical = (boosted.vertical or 1) * (KiteVertical.Value / 100)
						return old(root, mass, dir, boosted, ...)
					end

					local chance = rand:NextNumber(0, 100)
					chance = math.floor(chance)
					if Mode.Value == 'Default' then
						if chance >= Chance.Value then return old(root, mass, dir, knockback, ...) end
					end

					if check then
						knockback = knockback or {}
						if Mode.Value == 'Lag' then
							if chance < Chance.Value then
								return vapeEvents.TakeKnockback:Fire(root, mass, dir, knockback, ...)
							end
						else
							if Horizontal.Value == 0 and Vertical.Value == 0 then return end
							knockback.horizontal = (knockback.horizontal or 1) * (Horizontal.Value / 100)
							knockback.vertical = (knockback.vertical or 1) * (Vertical.Value / 100)
						end
					end

					return old(root, mass, dir, knockback, ...)
				end
			else
				bedwars.KnockbackUtil.applyKnockback = old
				old = nil
			end
		end
	})
	Mode = Velocity:CreateDropdown({
		Name = "Mode",
		List = {'Lag','Default'},
		Function = function(val)
			local isDefault = val == 'Default'
			if Horizontal then Horizontal.Object.Visible = isDefault end
			if Vertical then Vertical.Object.Visible = isDefault end
			if DelayGround then DelayGround.Object.Visible = not isDefault end
			if DelayAir then DelayAir.Object.Visible = not isDefault end
		end
	})
	Vertical = Velocity:CreateSlider({
		Name = "Vertical",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Visible = (Mode.Value == 'Default')
	})
	Horizontal = Velocity:CreateSlider({
		Name = "Horizontal",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Visible = (Mode.Value == 'Default')
	})
	DelayGround = Velocity:CreateSlider({
		Name = "Delay Ground",
		Min = 0,
		Max = 3000,
		Default = 1000,
		Suffix = 'ms',
		Decimal = 1,
		Visible = (Mode.Value == 'Lag')
	})
	DelayAir = Velocity:CreateSlider({
		Name = "Delay Air",
		Min = 0,
		Max = 3000,
		Default = 1000,
		Suffix = 'ms',
		Decimal = 1,
		Visible = (Mode.Value == 'Lag')
	})
	Targetting = Velocity:CreateToggle({
		Name = 'Only when targetting',
		Default = false
	})
	Chance = Velocity:CreateSlider({
		Name = "Chance",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Suffix = '%',
		Tooltip = 'how often it actually changes ur knockback, 100 means every hit'
	})
	KiteMode = Velocity:CreateToggle({
		Name = 'Kite Mode',
		Tooltip = 'boosts ur knockback when ur not facing them so u fly further away when runnin',
		Function = function(callback)
			if KiteHorizontal then KiteHorizontal.Object.Visible = callback end
			if KiteVertical then KiteVertical.Object.Visible = callback end
			if AlwaysKite then AlwaysKite.Object.Visible = callback end
		end
	})
	KiteHorizontal = Velocity:CreateSlider({
		Name = 'Kite Horizontal',
		Min = 100,
		Max = 200,
		Default = 120,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	KiteVertical = Velocity:CreateSlider({
		Name = 'Kite Vertical',
		Min = 100,
		Max = 200,
		Default = 120,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	AlwaysKite = Velocity:CreateToggle({
		Name = 'Always Kite',
		Tooltip = 'boosts ur knockback on every hit even when ur facin them',
		Darker = true,
		Visible = false
	})
end)

--[[
	Blatant Modules
]]

run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local PredictionScale
	local FOV
	local HitChance
	local HeadshotChance
	local OtherProjectiles
	local Blacklist
	local MiloCheck

	local RayCheck = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include

	local RandomGenerator = Random.new()

	local TargetLimbs = {
		Torso = {'UpperTorso', 'LowerTorso'},
		['Left arm'] = {'LeftUpperArm', 'LeftLowerArm', 'LeftHand'},
		['Right arm'] = {'RightUpperArm', 'RightLowerArm', 'RightHand'},
		['Left leg'] = {'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot'},
		['Right leg'] = {'RightUpperLeg', 'RightLowerLeg', 'RightFoot'}
	}
	local LimbOrder = {'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg'}
	local RandomLimb = setmetatable({}, {__mode = 'k'})

	local function isHeadshotProjectile(itemType)
		if not itemType then return false end
		local lower = tostring(itemType):lower()
		if lower:find('headhunter', 1, true) or lower:find('tactical', 1, true) then
			return true
		end
		return store.equippedKit == 'archer'
	end

	local function isDisguised(ent)
		if not ent.Player then return false end
		return workspace:FindFirstChild('DisguisedPlayerBlock_' .. ent.Player.UserId) ~= nil
	end

	local function getTargetPart(ent, mode)
		if mode == 'Random' and ent.Character then
			local pick = RandomLimb[ent.Character]
			if not pick or tick() > pick.Clock then
				pick = {Value = LimbOrder[math.random(1, #LimbOrder)], Clock = tick() + 1}
				RandomLimb[ent.Character] = pick
			end
			mode = pick.Value
		end

		if mode == 'Head' then
			return (ent.Character and ent.Character:FindFirstChild('Head')) or ent.Head or ent.RootPart
		end

		local limbs = TargetLimbs[mode]
		if limbs and ent.Character then
			for _, v in limbs do
				local part = ent.Character:FindFirstChild(v)
				if part then
					return part
				end
			end
		end

		return ent.RootPart
	end

	local Motion = setmetatable({}, {__mode = 'k'})
	local function getHitChance(ent, flight)
		if not flight or flight ~= flight or flight <= 0 then
			return 0
		end

		local root = ent.RootPart
		local velocity = root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
		local sample = Motion[root]
		if not sample then
			sample = {velocity = velocity, clock = os.clock(), accel = 0, speed = velocity.Magnitude}
			Motion[root] = sample
		end

		local step = os.clock() - sample.clock
		if step >= 0.05 then
			local blend = math.min(step * 5, 1)
			sample.accel += (((velocity - sample.velocity).Magnitude / step) - sample.accel) * blend
			sample.speed += (velocity.Magnitude - sample.speed) * blend
			sample.velocity, sample.clock = velocity, os.clock()
		end

		local drift = math.max(sample.speed, velocity.Magnitude) * math.min(flight, 0.4) * math.clamp(sample.accel / 120, 0, 1)
		return 1 / (1 + ((drift / 3) ^ 2))
	end

	local function solveSilent(arguments)
		local origin, velocity, projType = arguments[4], arguments[6], arguments[3]
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or type(projType) ~= 'string' then
			return
		end

		if (not OtherProjectiles.Enabled) and not projType:find('arrow') then
			return
		end

		if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
			return
		end

		local meta = bedwars.ProjectileMeta[projType]
		if not meta then
			return
		end

		local speed = velocity.Magnitude
		if speed <= 0 then
			return
		end

		if RandomGenerator:NextNumber(0, 100) > HitChance:GetRandomValue() then
			return
		end

		local map = workspace:FindFirstChild('Map')
		if map ~= RayCheck.FilterDescendantsInstances[1] then
			RayCheck.FilterDescendantsInstances = map and {map} or {}
		end
		local gravity = meta.gravitationalAcceleration or 196.2

		local target = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = (Targets.NPCs and Targets.NPCs.Enabled) or false,
			Priority = Targets.Priority.Value,
			Wallcheck = Targets.Walls.Enabled,
			Sort = Sort.Value ~= 'Distance' and sortmethods[Sort.Value] or nil,
			MouseOrigin = gameCamera.ViewportSize / 2,
			Origin = origin,
			Check = function(candidate)
				return not (MiloCheck.Enabled and isDisguised(candidate))
			end
		})
		if not target then
			return
		end

		local partName = RandomGenerator:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and 'Head' or TargetPart.Value
		local selectedPart = getTargetPart(target, partName)
		local targetPosition
		if partName == 'Closest' then
			local center, closestDistance = gameCamera.ViewportSize / 2, 9e9
			for _, v in target.Character:GetChildren() do
				if v:IsA('BasePart') then
					local screenPosition, visible = gameCamera:WorldToViewportPoint(v.Position)
					if visible then
						local partDistance = (center - Vector2.new(screenPosition.X, screenPosition.Y)).Magnitude
						if partDistance < closestDistance then
							closestDistance, targetPosition = partDistance, v.Position
						end
					end
				end
			end
			targetPosition = targetPosition or target.Character.PrimaryPart and target.Character.PrimaryPart.Position
		elseif partName == 'Dynamic' then
			local tool = store.hand.tool
			if isHeadshotProjectile(tool and tool.Name) and target.Character:FindFirstChild('Head') then
				targetPosition = target.Character.Head.Position
			else
				targetPosition = target.Character.PrimaryPart and target.Character.PrimaryPart.Position
			end
		end

		targetPosition = targetPosition or selectedPart and selectedPart.Position
		if not targetPosition then
			return
		end
		local playerGravity = workspace.Gravity
		local balloons = target.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end

		if target.Character.PrimaryPart and target.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
			playerGravity = 6
		end

		if target.Player and target.Player:GetAttribute('IsOwlTarget') then
			for _, v in collectionService:GetTagged('Owl') do
				if v:GetAttribute('Target') == target.Player.UserId and v:GetAttribute('Status') == 2 then
					playerGravity = 0
				end
			end
		end

		local isPearl = projType == 'telepearl'
		local targetVelocity = isPearl and Vector3.zero or target.RootPart.AssemblyLinearVelocity
		local targetAirborne = (not isPearl and target.Humanoid and target.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(targetVelocity.Y) > 0.01
		local aimPosition, _, travelTime = prediction.SolveTrajectory(origin, speed * PredictionScale.Value, gravity, targetPosition, targetVelocity, playerGravity, target.HipHeight, target.Jumping and 42.6 or nil, RayCheck, targetAirborne, target.RootPart.Position, target.RootPart, nil, true)
		if not aimPosition or not travelTime or travelTime > (meta.lifetimeSec or 3) then
			return
		end

		if targetinfo and targetinfo.Targets then
			targetinfo.Targets[target] = tick() + 1
		end
		store.hitchance = store.hitchance or {}
		store.hitchance.SilentAim = {Value = getHitChance(target, travelTime), Clock = tick()}
		return CFrame.lookAt(origin, aimPosition).LookVector * speed
	end

	local projectileAim = {Shots = {}, Solvers = {}, Active = true}
	vape.Libraries.projectileaim = projectileAim
	projectileAim.Solvers.SilentAim = solveSilent

	function projectileAim.Resolve(args, side)
		local id = args[7]
		if not projectileAim.Active or type(id) ~= 'string' or id == ''
			or typeof(args[4]) ~= 'Vector3' or typeof(args[6]) ~= 'Vector3' or args[6].Magnitude <= 0 then return end
		local now = os.clock()
		for key, entry in projectileAim.Shots do
			if now - entry.At > 2 then projectileAim.Shots[key] = nil end
		end
		local entry = projectileAim.Shots[id]
		if entry and entry.Type == args[3] and entry.Side ~= side then
			projectileAim.Shots[id] = nil
			return entry
		end
		local pa = vape.Modules.ProjectileAimbot
		local mode = SilentAim.Enabled and 'SilentAim' or pa and pa.Enabled and 'ProjectileAimbot'
		local solver = mode and projectileAim.Solvers[mode]
		local prepared = table.clone(args)
		local ok, velocity
		if solver then
			ok, velocity = pcall(solver, prepared)
		end
		local aimed = ok and typeof(velocity) == 'Vector3' and velocity.Magnitude > 0
		entry = {Type = args[3], Side = side, At = now, Velocity = aimed and velocity or nil, Data = aimed and prepared[8] or nil}
		projectileAim.Shots[id] = entry
		return entry
	end

	local function localProjectile(...)
		if not projectileAim.Active or (checkcaller and checkcaller()) then
			return projectileAim.Local(...)
		end
		local args = table.pack(...)
		local offset = typeof(args[4]) == 'Vector3' and 0 or typeof(args[5]) == 'Vector3' and 1 or nil
		if offset then
			local shot = {
				liveHandTool() or (store.hand and store.hand.tool), args[2 + offset], args[3 + offset],
				args[4 + offset], nil, args[6 + offset], args[5 + offset], args[7 + offset]
			}
			local entry = projectileAim.Resolve(shot, 'local')
			if entry and entry.Velocity then
				args[6 + offset] = entry.Velocity
				if entry.Data then args[7 + offset] = entry.Data end
			end
		end
		return projectileAim.Local(table.unpack(args, 1, args.n))
	end

	function projectileAim.Install()
		local controller = bedwars.ProjectileController
		if not projectileAim.Local and controller and type(controller.createLocalProjectile) == 'function' then
			projectileAim.Local = controller.createLocalProjectile
			controller.createLocalProjectile = localProjectile
		end
		if projectileAim.Namecall or not hookmetamethod then return end
		local wrap = newcclosure or function(func) return func end
		projectileAim.Namecall = hookmetamethod(game, '__namecall', wrap(function(...)
			if not projectileAim.Active or (checkcaller and checkcaller()) or getnamecallmethod() ~= 'InvokeServer' then
				return projectileAim.Namecall(...)
			end
			local remote = ...
			if typeof(remote) ~= 'Instance' or remote.Name ~= 'ProjectileFire' then
				return projectileAim.Namecall(...)
			end
			local args = table.pack(select(2, ...))
			local entry = projectileAim.Resolve(args, 'packet')
			if entry and entry.Velocity then
				args[6] = entry.Velocity
				if entry.Data then args[8] = entry.Data end
			end
			return projectileAim.Namecall(remote, table.unpack(args, 1, args.n))
		end))
	end

	vape:Clean(function()
		projectileAim.Active = false
		table.clear(projectileAim.Shots)
		local controller = bedwars.ProjectileController
		if controller and controller.createLocalProjectile == localProjectile then
			controller.createLocalProjectile = projectileAim.Local
		end
	end)

	SilentAim = vape.Categories.Blatant:CreateModule({
		Name = 'SilentAim',
		Function = function(callback)
			if callback then
				projectileAim.Install()
			end
		end,
		Tooltip = 'Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen'
	})

	Targets = SilentAim:CreateTargets({
		Players = true,
		Walls = true
	})
	TargetPart = SilentAim:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic', 'Closest'}
	})
	local sortList = {'Damage', 'Distance'}
	for _, v in getSortList({'Threat', 'Health', 'Angle', 'Cursor'}) do
		if not table.find(sortList, v) then
			table.insert(sortList, v)
		end
	end
	Sort = SilentAim:CreateDropdown({
		Name = 'Target Mode',
		List = sortList,
		Default = 'Distance'
	})
	PredictionScale = SilentAim:CreateSlider({
		Name = 'Prediction',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	HitChance = SilentAim:CreateTwoSlider({
		Name = 'Hit Chance',
		Min = 0,
		Max = 100,
		DefaultMin = 100,
		DefaultMax = 100,
		Tooltip = 'Chance in % for each shot to be redirected, rolled fresh between the two values on every shot. A missed roll leaves the shot where you aimed'
	})
	HeadshotChance = SilentAim:CreateTwoSlider({
		Name = 'Headshot Chance',
		Min = 0,
		Max = 100,
		DefaultMin = 0,
		DefaultMax = 0,
		Tooltip = 'Chance in % for each redirected shot to aim at the head instead of the Part setting, rolled fresh between the two values on every shot'
	})
	OtherProjectiles = SilentAim:CreateToggle({
		Name = 'Other Projectiles',
		Function = function(callback)
			if Blacklist then
				Blacklist.Object.Visible = callback
			end
		end,
		Default = true
	})
	Blacklist = SilentAim:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile'
	})
	MiloCheck = SilentAim:CreateToggle({
		Name = 'Milo check',
		Default = true,
		Tooltip = 'Skips Milo players while they are disguised as a block'
	})
end)

local AntiFallDirection
run(function()
    local AntiFall
    local Mode
    local Material
    local Color
	local rayCheck = cloneRaycast()
    rayCheck.RespectCanCollide = true

    local math_huge = math.huge
    local tick = tick
    local task_wait = task.wait
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    
    local cachedLowGround = math_huge
    local lastGroundScan = 0
    local groundScanInterval = 2 
    
    local function getLowGround()
        local now = tick()
        if now - lastGroundScan < groundScanInterval and cachedLowGround ~= math_huge then
            return cachedLowGround
        end
        
        lastGroundScan = now
        local mag = math_huge
        local blockStore = bedwars.BlockController:getStore()
        local allPositions = blockStore:getAllBlockPositions()
        
        for i = 1, #allPositions do
            local pos = allPositions[i] * 3
            if pos.Y < mag and not getPlacedBlock(pos + vector3new(0, 3, 0)) then
                mag = pos.Y
            end
        end
        
        cachedLowGround = mag
        return mag
    end

    AntiFall = vape.Categories.Blatant:CreateModule({
        Name = 'AntiFall',
        Function = function(callback)
            if callback then
                repeat task_wait() until store.matchState ~= 0 or (not AntiFall.Enabled)
                if not AntiFall.Enabled then return end

                local pos, debounce = getLowGround(), tick()
                if pos ~= math_huge then
                    AntiFallPart = Instance.new('Part')
                    AntiFallPart.Size = vector3new(10000, 1, 10000)
                    AntiFallPart.Transparency = 1 - Color.Opacity
                    AntiFallPart.Material = Enum.Material[Material.Value]
                    AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                    AntiFallPart.Position = vector3new(0, pos - 2, 0)
                    AntiFallPart.CanCollide = Mode.Value == 'Collide'
                    AntiFallPart.Anchored = true
                    AntiFallPart.CanQuery = false
                    AntiFallPart.Parent = workspace
                    AntiFall:Clean(AntiFallPart)
                    
                    AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
                        if touched.Parent == lplr.Character and entitylib.isAlive and debounce < tick() then
                            debounce = tick() + 0.1
                            
                            if Mode.Value == 'Normal' then
                                local top = getNearGround()
                                if top then
                                    local lastTeleport = lplr:GetAttribute('LastTeleported')
                                    local connection
                                    local frameCounter = 0
                                    
                                    local vapeModules = vape.Modules
                                    local flyEnabled = vapeModules.Fly
                                    local infFlyEnabled = vapeModules.InfiniteFly
                                    local longJumpEnabled = vapeModules.LongJump
                                    
                                    local yMask = vector3new(1, 0, 1)
                                    local yOnly = vector3new(0, 1, 0)
                                    
                                    connection = runService.PreSimulation:Connect(function()
                                        frameCounter = frameCounter + 1
                                        
                                        if frameCounter % 5 == 0 then
                                            if flyEnabled.Enabled or infFlyEnabled.Enabled or longJumpEnabled.Enabled then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                                return
                                            end
                                        end

                                        if entitylib.isAlive and lplr:GetAttribute('LastTeleported') == lastTeleport then
                                            local root = entitylib.character.RootPart
                                            local rootPos = root.Position
                                            local delta = (top - rootPos) * yMask
                                            
                                            AntiFallDirection = delta.Unit == delta.Unit and delta.Unit or vector3zero
                                            root.Velocity *= yMask
                                            
                                            if frameCounter % 3 == 0 then
                                                rayCheck.FilterDescendantsInstances = {gameCamera, lplr.Character}
                                                rayCheck.CollisionGroup = root.CollisionGroup

                                                local ray = workspace:Raycast(rootPos, AntiFallDirection, rayCheck)
                                                if ray then
                                                    for i = 1, 5 do
                                                        local dpos = roundPos(ray.Position + ray.Normal * 1.5) + vector3new(0, 3, 0)
                                                        if not getPlacedBlock(dpos) then
                                                            top = vector3new(top.X, pos.Y, top.Z)
                                                            break
                                                        end
                                                    end
                                                end
                                            end

                                            local yDiff = top.Y - rootPos.Y
                                            root.CFrame += vector3new(0, yDiff, 0)
                                            
                                            if not frictionTable.Speed then
                                                local speed = getSpeed()
                                                local newVelocity = (AntiFallDirection * speed) + vector3new(0, root.AssemblyLinearVelocity.Y, 0)
                                                root.AssemblyLinearVelocity = newVelocity
                                            end

                                            if delta.Magnitude < 1 then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                            end
                                        else
                                            connection:Disconnect()
                                            AntiFallDirection = nil
                                        end
                                    end)
                                    AntiFall:Clean(connection)
                                end
                            elseif Mode.Value == 'Velocity' then
                                local rootVel = entitylib.character.RootPart.Velocity
                                entitylib.character.RootPart.Velocity = vector3new(rootVel.X, 100, rootVel.Z)
                            end
                        end
                    end))
                end
            else
                AntiFallDirection = nil
                cachedLowGround = math_huge
                lastGroundScan = 0
            end
        end,
        Tooltip = 'Help\'s you with your Parkinson\'s\nPrevents you from falling into the void.'
    })
    
    Mode = AntiFall:CreateDropdown({
        Name = 'Move Mode',
        List = {'Normal', 'Collide', 'Velocity'},
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.CanCollide = val == 'Collide'
            end
        end,
        Tooltip = 'Normal - Smoothly moves you towards the nearest safe point\nVelocity - Launches you upward after touching\nCollide - Allows you to walk on the part'
    })
    
    local materials = {'ForceField'}
    for _, v in Enum.Material:GetEnumItems() do
        if v.Name ~= 'ForceField' then
            table.insert(materials, v.Name)
        end
    end
    
    Material = AntiFall:CreateDropdown({
        Name = 'Material',
        List = materials,
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.Material = Enum.Material[val]
            end
        end
    })
    
    Color = AntiFall:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.5,
        Function = function(h, s, v, o)
            if AntiFallPart then
                AntiFallPart.Color = Color3.fromHSV(h, s, v)
                AntiFallPart.Transparency = 1 - o
            end
        end
    })
end)

run(function()
    local _sharedHitBlock = nil
    local _hitBlockPatchers = {}

    getgenv().registerHitBlockPatch = function(key, fn)
        _hitBlockPatchers[key] = fn
        if not _sharedHitBlock and bedwars.BlockBreaker then
            _sharedHitBlock = bedwars.BlockBreaker.hitBlock
        end
        if not bedwars.BlockBreaker then return end
        bedwars.BlockBreaker.hitBlock = function(self, maid, raycastparams, ...)
            for _, patcher in _hitBlockPatchers do
                local result = patcher(self, maid, raycastparams, ...)
                if result ~= nil then return result end
            end
            if _sharedHitBlock then return _sharedHitBlock(self, maid, raycastparams, ...) end
        end
    end

    getgenv().unregisterHitBlockPatch = function(key)
        _hitBlockPatchers[key] = nil
        if not next(_hitBlockPatchers) then
            if bedwars.BlockBreaker then
                bedwars.BlockBreaker.hitBlock = _sharedHitBlock
            end
            _sharedHitBlock = nil
        end
    end

    local FastBreak
    local Time
    local BedCheck
    local Blacklist
    local blocks
    local string_lower = string.lower
    local string_find = string.find
    local task_wait = task.wait
    local currentBlock = nil
    local oldHitBlock = nil
    local lastHotbarSlot = nil
    local bedCache = {}
    local blacklistCache = {}
    local lastCacheClean = 0
    local cacheCleanInterval = 5 
    
    local function isBed(block)
        if not block then return false end
        local cached = bedCache[block]
        if cached ~= nil then return cached end
        
        local result = false
        pcall(function()
            if collectionService:HasTag(block, 'bed') or (block.Parent and collectionService:HasTag(block.Parent, 'bed')) then
                result = true
            elseif string_find(string_lower(block.Name), 'bed', 1, true) then
                result = true
            end
        end)
        
        if result then bedCache[block] = true end
        return result
    end
    
    local cachedBlacklistLower = {}
    local function updateBlacklistCache()
        if not blocks or not blocks.ListEnabled then return end
        
        cachedBlacklistLower = {}
        for _, v in pairs(blocks.ListEnabled) do
            table.insert(cachedBlacklistLower, string_lower(v))
        end
    end
    
    local function isBlacklisted(block)
        if not block or #cachedBlacklistLower == 0 then return false end
        local cached = blacklistCache[block]
        if cached ~= nil then return cached end
        
        local name = string_lower(block.Name)
        local result = false
        for i = 1, #cachedBlacklistLower do
            if string_find(name, cachedBlacklistLower[i], 1, true) then
                result = true
                break
            end
        end
        
        blacklistCache[block] = result
        return result
    end
    
    local function shouldSkip(block)
        if not block then return false end
        if BedCheck and BedCheck.Enabled and isBed(block) then return true end
        if Blacklist and Blacklist.Enabled and isBlacklisted(block) then return true end
        return false
    end
    
    local lastBreakUpdate = 0
    local breakUpdateCooldown = 0.05
    local pendingUpdate = false
    
    local function updateBreakSpeed()
        if not FastBreak or not FastBreak.Enabled then return end
        local now = tick()
        if now - lastBreakUpdate < breakUpdateCooldown then
            pendingUpdate = true
            return
        end
        lastBreakUpdate = now
        pendingUpdate = false
        
        pcall(function()
            local cooldown = (shouldSkip(currentBlock)) and 0.3 or Time.Value
            bedwars.BlockBreakController.blockBreaker:setCooldown(cooldown)
        end)
    end
    
    FastBreak = vape.Categories.Blatant:CreateModule({
        Name = 'FastBreak',
        Function = function(callback)
            if callback then
                lastHotbarSlot = nil

				registerHitBlockPatch('FastBreak', function(self, maid, raycastparams, ...)
					local block = nil
					pcall(function()
						local blockInfo = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = raycastparams})
						if blockInfo and blockInfo.target and blockInfo.target.blockInstance then
							block = blockInfo.target.blockInstance
						end
					end)
					
					local currentSlot = store.inventory and store.inventory.hotbarSlot
					local slotChanged = currentSlot ~= lastHotbarSlot
					if slotChanged then
						lastHotbarSlot = currentSlot
					end

					if block ~= currentBlock or slotChanged then
						currentBlock = block
						updateBreakSpeed()
					end
					end)
                
                updateBlacklistCache()
                
                task.spawn(function()
                    while FastBreak.Enabled do
                        if tick() - lastCacheClean > cacheCleanInterval then
                            lastCacheClean = tick()
                            bedCache = {}
                            blacklistCache = {}
                        end
                        if pendingUpdate then updateBreakSpeed() end
                        task_wait(0.05) 
                    end
                end)
			else
				pcall(function() bedwars.BlockBreakController.blockBreaker:setCooldown(0.3) end)
				unregisterHitBlockPatch('FastBreak')
				currentBlock = nil
				lastHotbarSlot = nil
				bedCache, blacklistCache, cachedBlacklistLower = {}, {}, {}
			end
        end,
        Tooltip = 'mine faster'
    })
    
    Time = FastBreak:CreateSlider({
        Name = 'Break speed',
        Min = 0, Max = 0.3, Default = 0.25, Decimal = 100, Suffix = 'seconds',
        Function = function() updateBreakSpeed() end
    })
    
    BedCheck = FastBreak:CreateToggle({
        Name = 'Bed Check',
        Default = false,
        Tooltip = 'mining is normal when breaking beds',
        Function = function() bedCache = {}; updateBreakSpeed() end
    })
    
    Blacklist = FastBreak:CreateToggle({
        Name = 'Blacklist Blocks',
        Default = false,
        Tooltip = 'mining is normal for blacklisted blocks',
        Function = function(v)
            if blocks then blocks.Object.Visible = v end
            blacklistCache = {}
            if v then updateBlacklistCache() end
            updateBreakSpeed()
        end
    })
    
    blocks = FastBreak:CreateTextList({
        Name = 'Blacklisted Blocks',
        Placeholder = 'bed',
        Visible = false,
        Function = function()
            updateBlacklistCache()
            blacklistCache = {}
            updateBreakSpeed()
        end
    })
end)

run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TP
    local lastonground = false
    local MobileButtons
    local FlyAnywayProgressBar = {Enabled = false}
    local FlyAnywayProgressBarFrame
    local BarColor
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local up, down, old = 0, 0
    local mobileControls = {}
    local groundtime = nil
    local onground = false
    local flyCooldownActive = false
    local lastGroundTouchTime = 0
    local MAX_FLY_TIME = 2.5
    local tick = tick
    local task_wait = task.wait
    local math_max = math.max
    local math_floor = math.floor
    local string_format = string.format
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    local udim2new = UDim2.new
    local cframeLookAlong = CFrame.lookAlong
    local cachedBalloonCount = 0
    local lastBalloonCheck = 0
    local balloonCheckInterval = 0.2 
    local cachedMatchState = 0
    local lastMatchStateCheck = 0
    local lastGroundTime = tick()
    local airTime = 0
    
    local function createMobileButton(name, position, icon)
        local button = Instance.new("TextButton")
        button.Name = name
        button.Size = udim2new(0, 60, 0, 60)
        button.Position = position
        button.BackgroundTransparency = 0.2
        button.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        button.BorderSizePixel = 0
        button.Text = icon
        button.TextScaled = true
        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.Font = Enum.Font.SourceSansBold
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 8)
        corner.Parent = button
        return button
    end

    local function cleanupMobileControls()
        for _, control in pairs(mobileControls) do
            if control then
                control:Destroy()
            end
        end
        mobileControls = {}
    end

    local progressBarFrameCounter = 0
    local MAX_FRAME_COUNTER = 600
    local function updateProgressBar()
        if not FlyAnywayProgressBarFrame then return end

        if (TP and TP.Enabled) or not entitylib.isAlive then
            FlyAnywayProgressBarFrame.Visible = false
            return
        end
        
        local now = tick()
        if now - lastBalloonCheck > balloonCheckInterval then
            lastBalloonCheck = now
            cachedBalloonCount = lplr.Character:GetAttribute('InflatedBalloons') or 0
            cachedMatchState = store.matchState
        end
        
        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
        
        if flyAllowed then
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = "∞"
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled
            return
        end
        
        progressBarFrameCounter = (progressBarFrameCounter + 1) % MAX_FRAME_COUNTER
        if progressBarFrameCounter % 3 == 0 then
            local hipHeight = entitylib.character.Humanoid.HipHeight
            local checkPos = entitylib.character.HumanoidRootPart.Position + vector3new(0, (hipHeight * -2) - 1, 0)
            local newray = getPlacedBlock(checkPos)
            onground = newray ~= nil
        end
        
        if onground then
            groundtime = nil
            flyCooldownActive = false
            lastGroundTouchTime = now
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", MAX_FLY_TIME)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            local tween = FlyAnywayProgressBarFrame.Frame:FindFirstChild("Tween")
            if tween then
                tween:Destroy()
            end
        else
            if not groundtime then
                groundtime = now + MAX_FLY_TIME
                flyCooldownActive = false
            end
            
            local timeLeft = math_max(0, groundtime - now)
            local progress = timeLeft / MAX_FLY_TIME
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(progress, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", timeLeft)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            if timeLeft <= 0 and not flyCooldownActive then
                flyCooldownActive = true
            end
        end
        
        lastonground = onground
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = 'Fly',
        Function = function(callback)
            frictionTable.Fly = callback or nil
            updateVelocity()
            if callback then
                up, down, old = 0, 0, bedwars.BalloonController.deflateBalloon
                bedwars.BalloonController.deflateBalloon = function() end
                local tpTick, tpToggle, oldy = tick(), true

                if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                    bedwars.BalloonController:inflateBalloon()
                end

                Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(changed)
                    if changed == 'InflatedBalloons' then
                        local char = lplr.Character
                        if not char then return end
                        cachedBalloonCount = char:GetAttribute('InflatedBalloons') or 0
                        if cachedBalloonCount == 0 and getItem('balloon') then
                            bedwars.BalloonController:inflateBalloon()
                        end
                    end
                end))

                local renderFrameCounter = 0
                Fly:Clean(runService.RenderStepped:Connect(function(delta)
                    if FlyAnywayProgressBar.Enabled and Fly.Enabled then
                        renderFrameCounter = renderFrameCounter + 1
                        if renderFrameCounter % 2 == 0 then
                            updateProgressBar()
                        end
                    end
                end))

                local preSimFrameCounter = 0
                local lastWallRaycast = 0
                local wallRaycastInterval = 0.05
                
                Fly:Clean(runService.PreSimulation:Connect(function(dt)
                    if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) then
                        preSimFrameCounter = preSimFrameCounter + 1
                        local now = tick()
                        
                        if preSimFrameCounter % 12 == 0 then
                            cachedBalloonCount = lplr.Character and lplr.Character:GetAttribute('InflatedBalloons') or 0
                            cachedMatchState = store.matchState
                        end

                        local humanoid = entitylib.character.Humanoid
                        if humanoid.FloorMaterial ~= Enum.Material.Air then
                            lastGroundTime = now
                        end
                        airTime = now - lastGroundTime
                        
                        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
                        
                        local oscillation = (now % 0.4 < 0.2) and -1 or 1
                        local mass = (1.95 + (flyAllowed and 6 or 0) * oscillation) + ((up + down) * VerticalValue.Value)
                        
                        local root = entitylib.character.RootPart
                        local moveDirection = entitylib.character.Humanoid.MoveDirection
                        local velo = getSpeed()
                        local destination = (moveDirection * math_max(Value.Value - velo, 0) * dt)
                        
                        if WallCheck.Enabled and (now - lastWallRaycast) > wallRaycastInterval then
                            lastWallRaycast = now
                            local filterList = {lplr.Character, gameCamera}
                            if AntiVoidPart then table.insert(filterList, AntiVoidPart) end
                            rayCheck.FilterDescendantsInstances = filterList
                            rayCheck.CollisionGroup = root.CollisionGroup

                            if destination.Magnitude > 0.001 then
                                local ray = workspace:Raycast(root.Position, destination, rayCheck)
                                if ray then
                                    destination = ((ray.Position + ray.Normal) - root.Position)
                                end
                            end
                        end

                        if not flyAllowed then
                            if tpToggle then
                                if airTime > 2 then  
                                    if not oldy then
                                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiVoidPart}
                                        rayCheck.CollisionGroup = root.CollisionGroup
                                        local ray = workspace:Raycast(root.Position, vector3new(0, -1000, 0), rayCheck)
                                        if ray and TP.Enabled then
                                            tpToggle = false
                                            oldy = root.Position.Y
                                            tpTick = now + 0.11
                                            root.CFrame = cframeLookAlong(vector3new(root.Position.X, ray.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector)
                                        end
                                    end
                                end
                            else
                                if oldy then
                                    if tpTick < now then
                                        local newpos = vector3new(root.Position.X, oldy, root.Position.Z)
                                        root.CFrame = cframeLookAlong(newpos, root.CFrame.LookVector)
                                        tpToggle = true
                                        oldy = nil
                                    else
                                        mass = 0
                                    end
                                end
                            end
                        end

                        root.CFrame += destination
                        root.AssemblyLinearVelocity = (moveDirection * velo) + vector3new(0, mass, 0)
                    end
                end))

                local isMobile = inputService.TouchEnabled and not inputService.KeyboardEnabled and not inputService.MouseEnabled
                local MobileEnabled = MobileButtons.Enabled or isMobile
                if MobileEnabled then
                    local gui = Instance.new("ScreenGui")
                    gui.Name = "FlyControls"
                    gui.ResetOnSpawn = false
                    gui.Parent = lplr.PlayerGui

                    local upButton = createMobileButton("UpButton", udim2new(0.9, -70, 0.7, -140), "↑")
                    local downButton = createMobileButton("DownButton", udim2new(0.9, -70, 0.7, -70), "↓")

                    mobileControls.UpButton = upButton
                    mobileControls.DownButton = downButton
                    mobileControls.ScreenGui = gui

                    upButton.Parent = gui
                    downButton.Parent = gui

                    Fly:Clean(upButton.MouseButton1Down:Connect(function()
                        up = 1
                    end))
                    Fly:Clean(upButton.MouseButton1Up:Connect(function()
                        up = 0
                    end))
                    Fly:Clean(downButton.MouseButton1Down:Connect(function()
                        down = -1
                    end))
                    Fly:Clean(downButton.MouseButton1Up:Connect(function()
                        down = 0
                    end))
                end

                Fly:Clean(inputService.InputBegan:Connect(function(input)
                    if not inputService:GetFocusedTextBox() then
                        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                            up = 1
                        elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                            down = -1
                        end
                    end
                end))
                Fly:Clean(inputService.InputEnded:Connect(function(input)
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        up = 0
                    elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                        down = 0
                    end
                end))
                if inputService.TouchEnabled then
                    pcall(function()
                        local jumpButton = lplr.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function()
                            if not mobileControls.UpButton then
                                up = jumpButton.ImageRectOffset.X == 146 and 1 or 0
                            end
                        end))
                    end)
                end
            else
                if FlyAnywayProgressBarFrame then
                    FlyAnywayProgressBarFrame.Visible = false
                end
                lastonground = nil
                groundtime = nil
                flyCooldownActive = false
                bedwars.BalloonController.deflateBalloon = old
                if PopBalloons.Enabled and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
                cleanupMobileControls()
                cachedBalloonCount = 0
                lastBalloonCheck = 0
                cachedMatchState = 0
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'makes you go zoom!'
    })
    Value = Fly:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    VerticalValue = Fly:CreateSlider({
        Name = 'Vertical Speed',
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = 'Pop Balloons',
        Default = true
    })
    FlyAnywayProgressBar = Fly:CreateToggle({
        Name = "Progress Bar",
        Function = function(callback)
            if BarColor and BarColor.Object then
                BarColor.Object.Visible = callback
            end
            if callback then
                FlyAnywayProgressBarFrame = Instance.new("Frame")
                FlyAnywayProgressBarFrame.AnchorPoint = Vector2.new(0.5, 0)
                FlyAnywayProgressBarFrame.Position = udim2new(0.5, 0, 1, -200)
                FlyAnywayProgressBarFrame.Size = udim2new(0.2, 0, 0, 20)
                FlyAnywayProgressBarFrame.BackgroundTransparency = 0.5
                FlyAnywayProgressBarFrame.BorderSizePixel = 0
                FlyAnywayProgressBarFrame.BackgroundColor3 = Color3.new(0, 0, 0)
                FlyAnywayProgressBarFrame.Visible = false
                FlyAnywayProgressBarFrame.Parent = vape.gui
                
                local FlyAnywayProgressBarFrame2 = Instance.new("Frame")
                FlyAnywayProgressBarFrame2.Name = "Frame"
                FlyAnywayProgressBarFrame2.AnchorPoint = Vector2.new(0, 0)
                FlyAnywayProgressBarFrame2.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBarFrame2.Size = udim2new(1, 0, 0, 20)
                FlyAnywayProgressBarFrame2.BackgroundTransparency = 0
                FlyAnywayProgressBarFrame2.BorderSizePixel = 0
                FlyAnywayProgressBarFrame2.BackgroundColor3 = BarColor and Color3.fromHSV(BarColor.H, BarColor.S, BarColor.V) or Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
                FlyAnywayProgressBarFrame2.Visible = true
                FlyAnywayProgressBarFrame2.Parent = FlyAnywayProgressBarFrame
                
                local FlyAnywayProgressBartext = Instance.new("TextLabel")
                FlyAnywayProgressBartext.Name = "TextLabel"
                FlyAnywayProgressBartext.Text = "2.5s"
                FlyAnywayProgressBartext.Font = Enum.Font.Gotham
                FlyAnywayProgressBartext.TextStrokeTransparency = 0
                FlyAnywayProgressBartext.TextColor3 = Color3.new(0.9, 0.9, 0.9)
                FlyAnywayProgressBartext.TextSize = 20
                FlyAnywayProgressBartext.Size = udim2new(1, 0, 1, 0)
                FlyAnywayProgressBartext.BackgroundTransparency = 1
                FlyAnywayProgressBartext.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBartext.Parent = FlyAnywayProgressBarFrame
            else
                if FlyAnywayProgressBarFrame then 
                    FlyAnywayProgressBarFrame:Destroy() 
                    FlyAnywayProgressBarFrame = nil 
                end
            end
        end,
        Tooltip = "show amount of time for fly",
        Default = true
    })
    BarColor = Fly:CreateColorSlider({
        Name = 'Bar Color',
        Darker = true,
        Visible = false,
        Function = function(h, s, v, o)
            if FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundColor3 = Color3.fromHSV(h, s, v)
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundTransparency = 1 - o
            end
        end
    })

    TP = Fly:CreateToggle({
        Name = 'TP Down',
        Default = true,
        Function = function(callback)
            if callback and FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame.Visible = false
            end
        end
    })
    MobileButtons = Fly:CreateToggle({
        Name = "Mobile Buttons",
        Visible = false,
        Tooltip = 'puts up n down buttons on ur screen gng',
        Function = function() 
            if Fly.Enabled then
                Fly:Toggle()
                Fly:Toggle()
            end
        end
    })

    task.defer(function()
        if BarColor and BarColor.Object then
            BarColor.Object.Visible = FlyAnywayProgressBar.Enabled
        end
        if MobileButtons and MobileButtons.Object then
            MobileButtons.Object.Visible = inputService.TouchEnabled
        end
    end)
end)

run(function()
	local NoSlowDown
    local old
    local SophiaCheck
    local FROZEN_THRESHOLD = 10
    local cachedModifier = nil
    local nsHooked = false
    local savedSlow = setmetatable({}, {__mode = 'k'})
    local origPunch = nil
    local origGroveDisable = nil

    local function hookKitNoSlow()
        if bedwars.DragonSlayerController and not origPunch then
            origPunch = bedwars.DragonSlayerController.playPunchAnimation
            bedwars.DragonSlayerController.playPunchAnimation = function(self, arg2)
                local ok, maid = pcall(function()
                    local imp = debug.getupvalue(origPunch, 1)
                    local anim = debug.getupvalue(origPunch, 2)
                    local plrs = debug.getupvalue(origPunch, 3)
                    local atype = debug.getupvalue(origPunch, 4)
                    local rs = debug.getupvalue(origPunch, 6)
                    local m = imp.new()
                    local track = anim:playAnimation(plrs.LocalPlayer, atype.DRAGON_SLAYER_PUNCH)
                    m:GiveTask(function()
                        if track then track:Stop() end
                    end)
                    m:GiveTask(rs.Heartbeat:Connect(function()
                        local char = plrs.LocalPlayer.Character
                        if not char or not char.PrimaryPart then
                            m:DoCleaning()
                            return
                        end
                        char:PivotTo(CFrame.new(char:GetPrimaryPartCFrame().Position) * arg2)
                    end))
                    task.delay(0.46, function() m:DoCleaning() end)
                    return m
                end)
                if ok and maid then return maid end
                return origPunch(self, arg2)
            end
        end

        if bedwars.SpiritGardenerController and not origGroveDisable then
            origGroveDisable = bedwars.SpiritGardenerController.disableActionsOnCharge
            bedwars.SpiritGardenerController.disableActionsOnCharge = function(self, maid, character)
                if character ~= lplr.Character then
                    return origGroveDisable(self, maid, character)
                end
                local ok = pcall(function()
                    local KnitClient = bedwars.KnitClient
                    KnitClient.Controllers.SwordController:toggleSwordSwing(true)
                    KnitClient.Controllers.BlockPlacementController:disableBlockPlacer()
                    local ClientSyncEvents = debug.getupvalue(origGroveDisable, 3)
                    local projConn = ClientSyncEvents.BeginProjectileTargeting:connect(function(event)
                        event:setCancelled(true)
                    end)
                    local jumpMod = KnitClient.Controllers.JumpHeightController:getJumpModifier():addModifier({
                        jumpHeightMultiplier = 0
                    })
                    maid:GiveTask(function()
                        KnitClient.Controllers.SwordController:toggleSwordSwing(false)
                        KnitClient.Controllers.BlockPlacementController:enableBlockPlacer()
                        projConn:Destroy()
                        jumpMod.Destroy()
                    end)
                end)
                if not ok then
                    return origGroveDisable(self, maid, character)
                end
            end
        end
    end

    local function unhookKitNoSlow()
        if origPunch and bedwars.DragonSlayerController then
            bedwars.DragonSlayerController.playPunchAnimation = origPunch
        end
        origPunch = nil
        if origGroveDisable and bedwars.SpiritGardenerController then
            bedwars.SpiritGardenerController.disableActionsOnCharge = origGroveDisable
        end
        origGroveDisable = nil
    end
    NoSlowdown = vape.Categories.Blatant:CreateModule({
        Name = 'NoSlowdown',
        Function = function(callback)
            if not cachedModifier then
                if not bedwars.SprintController then return end
                cachedModifier = bedwars.SprintController:getMovementStatusModifier()
            end
            local modifier = cachedModifier
            if callback then
                if nsHooked then return end
                hookKitNoSlow()
                old = modifier.addModifier
                if not old then return end
                local orig = old

                local function removeSlow(tab)
                    if type(tab) ~= 'table' then
                        return false, false
                    end

                    local changed = false
                    local unblocked = false

                    if not savedSlow[tab] then
                        savedSlow[tab] = {
                            move = tab.moveSpeedMultiplier,
                            constant = tab.constantSpeedMultiplier,
                            blockSprint = tab.blockSprint
                        }
                    end

                    local move = tonumber(tab.moveSpeedMultiplier)
                    local constant = tonumber(tab.constantSpeedMultiplier)

                    if move and move < 1 then
                        tab.moveSpeedMultiplier = 1
                        changed = true
                    end

                    if constant and constant < 1 then
                        tab.constantSpeedMultiplier = 1
                        changed = true
                    end

                    if tab.blockSprint == true and not (constant and constant > 1) then
                        tab.blockSprint = false
                        changed = true
                        unblocked = true
                    end

                    return changed, unblocked
                end

                nsHooked = true
                modifier.addModifier = function(self, tab)
                    if not orig then return end

                    if SophiaCheck and SophiaCheck.Enabled and isFrozen(nil, FROZEN_THRESHOLD) then
                        return orig(self, tab)
                    end

                    removeSlow(tab)
                    return orig(self, tab)
                end

                local changed = false
                local unblocked = false

                for i, v in modifier.modifiers do
                    local mod = type(v) == 'table' and v or (type(i) == 'table' and i or nil)

                    if mod then
                        local didChange, didUnblock = removeSlow(mod)

                        if didChange then
                            changed = true
                        end

                        if didUnblock then
                            unblocked = true
                        end
                    end
                end

                if changed and modifier.updateModifiers then
                    modifier:updateModifiers()
                end

                if unblocked
                    and entitylib.isAlive
                    and entitylib.character.Humanoid.MoveDirection.Magnitude > 0 then

                    pcall(function()
                        bedwars.SprintController:startSprinting()
                    end)
                end

                NoSlowdown:Clean(runService.PreSimulation:Connect(function()
                    if not NoSlowdown.Enabled or not cachedModifier then
                        return
                    end

                    if SophiaCheck and SophiaCheck.Enabled and isFrozen(nil, FROZEN_THRESHOLD) then
                        return
                    end

                    local updated = false
                    local resumeSprint = false

                    for i, v in cachedModifier.modifiers do
                        local mod = type(v) == 'table' and v or (type(i) == 'table' and i or nil)

                        if mod then
                            local didChange, didUnblock = removeSlow(mod)

                            if didChange then
                                updated = true
                            end

                            if didUnblock then
                                resumeSprint = true
                            end
                        end
                    end

                    if updated and cachedModifier.updateModifiers then
                        cachedModifier:updateModifiers()
                    end

                    if resumeSprint
                        and entitylib.isAlive
                        and entitylib.character.Humanoid.MoveDirection.Magnitude > 0 then

                        pcall(function()
                            bedwars.SprintController:startSprinting()
                        end)
                    end
                end))
            else
                unhookKitNoSlow()
                if cachedModifier then
                    cachedModifier.addModifier = old
                    for tab, orig in savedSlow do
                        tab.moveSpeedMultiplier = orig.move
                        tab.constantSpeedMultiplier = orig.constant
                        tab.blockSprint = orig.blockSprint
                    end
                    if cachedModifier.updateModifiers then
                        pcall(cachedModifier.updateModifiers, cachedModifier)
                    end
                    cachedModifier = nil
                end
                table.clear(savedSlow)
                old = nil
                nsHooked = false
            end
        end,
        Tooltip = 'prevents slowing down when using items.'
    })

    SophiaCheck = NoSlowdown:CreateToggle({
        Name = 'Sophia Check',
        Default = false
    })
end)

run(function()
	local ProjectileAimbot
	local Targets
	local Sort
	local PartOption
	local FOV
	local Distance
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject
	local Horizontal
	local Vertical
	local AutoCharge
	local Aim
	local OtherProjectiles
	local UseUmeko
	local Potions
	local Blacklist
	local MiloCheck
	local Old, Hook
	local ArcCheck = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Include

	local TargetLimbs = {
		Torso = {'UpperTorso', 'LowerTorso'},
		['Left arm'] = {'LeftUpperArm', 'LeftLowerArm', 'LeftHand'},
		['Right arm'] = {'RightUpperArm', 'RightLowerArm', 'RightHand'},
		['Left leg'] = {'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot'},
		['Right leg'] = {'RightUpperLeg', 'RightLowerLeg', 'RightFoot'}
	}
	local LimbOrder = {'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg'}
	local RandomLimb = setmetatable({}, {__mode = 'k'})

	local function IsHeadshotProjectile(itemType)
		if not itemType then return false end
		local lower = tostring(itemType):lower()
		if lower:find('headhunter', 1, true) or lower:find('tactical', 1, true) then
			return true
		end
		return store.equippedKit == 'archer'
	end

	local function IsDisguised(Ent)
		if not Ent.Player then return false end
		return workspace:FindFirstChild('DisguisedPlayerBlock_' .. Ent.Player.UserId) ~= nil
	end

	local function GetTargetPart(Ent, Mode)
		if Mode == 'Random' and Ent.Character then
			local Pick = RandomLimb[Ent.Character]
			if not Pick or tick() > Pick.Clock then
				Pick = {Value = LimbOrder[math.random(1, #LimbOrder)], Clock = tick() + 1}
				RandomLimb[Ent.Character] = Pick
			end
			Mode = Pick.Value
		end

		if Mode == 'Head' then
			return (Ent.Character and Ent.Character:FindFirstChild('Head')) or Ent.Head or Ent.RootPart
		end

		local Limbs = TargetLimbs[Mode]
		if Limbs and Ent.Character then
			for _, v in Limbs do
				local Part = Ent.Character:FindFirstChild(v)
				if Part then
					return Part
				end
			end
		end

		return Ent.RootPart
	end

	local function GetMouseOrigin()
		if inputService.TouchEnabled then
			return gameCamera.ViewportSize / 2
		end
		return inputService:GetMouseLocation()
	end

	-- Some builds never run the launch method for a shot, so the outgoing packet is
	-- redirected as well. Only the direction is replaced: the speed, spawn position and
	-- draw the game computed stay untouched, which is the shot the server accepts.
	local paDebugAt = {}

	local function paLog(tag, text)
		if not PADebug or not PADebug.Enabled then
			return
		end
		local now = tick()
		if now - (paDebugAt[tag] or 0) < 0.5 then
			return
		end
		paDebugAt[tag] = now
		print('[ProjectileAimbot] ' .. tostring(text))
	end

	local function paSolve(Tool, ProjectileName, PositionFrom, NativeVelocity)
		if not ProjectileAimbot or not ProjectileAimbot.Enabled then
			return nil
		end
		if typeof(PositionFrom) ~= 'Vector3' or typeof(NativeVelocity) ~= 'Vector3' or type(ProjectileName) ~= 'string' then
			return nil
		end
		if ProjectileName:find('splash_potion', 1, true) then
			if not Potions.Enabled then
				return nil
			end
		elseif not OtherProjectiles.Enabled and not ProjectileName:find('arrow', 1, true)
			and not (UseUmeko.Enabled and ProjectileName:find('^ninja_chakram')) then
			return nil
		end
		local BlacklistName = (ProjectileName == 'glue_trap' or ProjectileName == 'glue_projectile') and 'gloop' or ProjectileName
		if table.find(Blacklist.ListEnabled or {}, BlacklistName) then
			return nil
		end
		local ProjectileMeta = bedwars.ProjectileMeta and bedwars.ProjectileMeta[ProjectileName]
		if type(ProjectileMeta) ~= 'table' then
			return nil
		end
		local Speed = NativeVelocity.Magnitude
		if Speed <= 0.001 or Speed > 10000 then
			return nil
		end
		local Gravity = tonumber(ProjectileMeta.gravitationalAcceleration) or 196.2
		if Gravity < 1 then Gravity = 0 end
		local Lifetime = tonumber(ProjectileMeta.predictionLifetimeSec) or tonumber(ProjectileMeta.lifetimeSec) or 3
		local BowConstants = bedwars.BowConstantsTable or {}
		local RelX, RelY, RelZ = BowConstants.RelX or 0.8, BowConstants.RelY or -0.6, BowConstants.RelZ or 0
		local ToolMeta = Tool and bedwars.ItemMeta and bedwars.ItemMeta[Tool.Name]
		local SourceMeta = ToolMeta and ToolMeta.projectileSource
		local Relative = SourceMeta and SourceMeta.relativeOverride
		if type(Relative) == 'table' then
			RelX, RelY, RelZ = Relative.relX or 0, Relative.relY or 0, Relative.relZ or 0
		end
		local map = workspace:FindFirstChild('Map')
		if map then
			ArcCheck.FilterDescendantsInstances = {map}
		end
		local PartName = PartOption.Value == 'Dynamic' and (IsHeadshotProjectile(Tool and Tool.Name) and 'Head' or 'RootPart') or PartOption.Value

		local function Solve(Ent)
			if not Ent.Character or not Ent.RootPart then
				return nil
			end
			local Balloons = Ent.Character:GetAttribute('InflatedBalloons')
			local PlayerGravity = workspace.Gravity
			if Balloons and Balloons > 0 then
				PlayerGravity = balloonGravity(Balloons, Ent.Character)
			end
			if Ent.Character.PrimaryPart and Ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
				PlayerGravity = 6
			end
			if Ent.Player and Ent.Player:GetAttribute('IsOwlTarget') then
				for _, v in collectionService:GetTagged('Owl') do
					if v:GetAttribute('Target') == Ent.Player.UserId and v:GetAttribute('Status') == 2 then
						PlayerGravity = 0
						break
					end
				end
			end

			local AimPart = GetTargetPart(Ent, PartName)
			local Velocity = Ent.RootPart.AssemblyLinearVelocity or Vector3.zero
			if Horizontal.Value ~= 1 or Vertical.Value ~= 1 then
				Velocity = Vector3.new(Velocity.X * Horizontal.Value, Velocity.Y * Vertical.Value, Velocity.Z * Horizontal.Value)
			end
			local Airborne = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(Velocity.Y) > 0.01
			local JumpVelocity = Ent.Jumping and 42.6 or nil
			local AimTarget = AimPart.Position

			local calc, flight
			calc, _, flight = prediction.SolveTrajectory(
				PositionFrom, Speed, Gravity,
				AimTarget, Velocity,
				PlayerGravity, Ent.HipHeight, JumpVelocity,
				ArcCheck, Airborne,
				Ent.RootPart.Position, Ent.RootPart,
				nil, true
			)
			for _ = 1, 2 do
				if not calc or not flight then break end
				local Spawn = prediction.GetSpawnPosition(PositionFrom, calc, RelX, RelY, RelZ)
				local corrected, _, correctedTime = prediction.SolveTrajectory(
					Spawn, Speed, Gravity,
					AimTarget, Velocity,
					PlayerGravity, Ent.HipHeight, JumpVelocity,
					ArcCheck, Airborne,
					Ent.RootPart.Position, Ent.RootPart,
					nil, true
				)
				if not corrected or not correctedTime then break end
				calc = PositionFrom + (corrected - Spawn)
				flight = correctedTime
			end
			if not calc or not flight or flight > Lifetime then
				return nil
			end

			if Targets.Walls.Enabled then
				local Spawn = prediction.GetSpawnPosition(PositionFrom, calc, RelX, RelY, RelZ)
				if not prediction.IsTrajectoryClear(Spawn, (calc - PositionFrom).Unit * Speed, Gravity, flight * 0.97, ArcCheck) then
					return nil
				end
			end

			return CFrame.lookAt(PositionFrom, calc).LookVector * Speed
		end

		local Value, Attempts, Started = nil, 0, os.clock()
		local Ent = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs and Targets.NPCs.Enabled or false,
			Wallcheck = Targets.Walls.Enabled or nil,
			Origin = PositionFrom,
			MouseOrigin = GetMouseOrigin(),
			Sort = sortmethods[Sort.Value],
			Check = function(Candidate)
				if MiloCheck.Enabled and IsDisguised(Candidate) then
					return false
				end
				local MyRoot = entitylib.character and entitylib.character.RootPart
				if MyRoot and (Candidate.RootPart.Position - MyRoot.Position).Magnitude > Distance.Value then
					return false
				end
				if Attempts >= 10 or (Attempts > 0 and (os.clock() - Started) > 0.0015) then
					return false
				end
				Attempts += 1
				Value = Solve(Candidate)
				return Value ~= nil
			end
		})

		if (not Ent or not Value) then
			-- Point blank the root part drops below the viewport and the cursor pass skips the
			-- enemy; take the nearest body in front of the camera instead.
			local MyRoot = entitylib.character and entitylib.character.RootPart
			local look = gameCamera.CFrame.LookVector
			local MaxClose = math.min(Distance.Value or 24, 24)
			local candidates = {}
			for _, candidate in entitylib.List do
				if candidate.Player and not Targets.Players.Enabled then continue end
				if candidate.NPC and not (Targets.NPCs and Targets.NPCs.Enabled) then continue end
				if not candidate.Targetable or not candidate.RootPart or not candidate.Character then continue end
				if not entitylib.isVulnerable(candidate) then continue end
				if MiloCheck.Enabled and IsDisguised(candidate) then continue end
				local delta = candidate.RootPart.Position - PositionFrom
				local dist3 = delta.Magnitude
				if dist3 > MaxClose or dist3 < 0.01 then continue end
				if look:Dot(delta.Unit) < 0.15 then continue end
				if MyRoot and (candidate.RootPart.Position - MyRoot.Position).Magnitude > Distance.Value then continue end
				table.insert(candidates, {ent = candidate, dist = dist3})
			end
			table.sort(candidates, function(a, b)
				return a.dist < b.dist
			end)
			for i = 1, math.min(#candidates, 5) do
				local candidate = candidates[i].ent
				if not Targets.Walls.Enabled or not entitylib.Wallcheck(PositionFrom, candidate.RootPart.Position, Targets.Walls.Enabled, candidate) then
					local solved = Solve(candidate)
					if solved then
						Ent, Value = candidate, solved
						break
					end
				end
			end
		end

		if Ent and Value then
			if targetinfo and targetinfo.Targets then
				targetinfo.Targets[Ent] = tick() + 1
			end
			return Value
		end
	end

	vape.Libraries.projectileaim.Solvers.ProjectileAimbot = function(args)
		return paSolve(args[1], args[3], args[4], args[6])
	end

	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		Function = function(callback)
			if not callback then
				local controller = bedwars.ProjectileController
				if Hook and controller and controller.calculateImportantLaunchValues == Hook then
					controller.calculateImportantLaunchValues = Old
				end
				Old, Hook = nil, nil
				if CircleObject then
					CircleObject.Visible = false
				end
				return
			end
			vape.Libraries.projectileaim.Install()

			if CircleObject then
				CircleObject.Visible = true
			end

			local function UpdateCircle()
				if CircleObject then
					CircleObject.Position = GetMouseOrigin()
				end
			end

			ProjectileAimbot:Clean(runService.RenderStepped:Connect(UpdateCircle))
			ProjectileAimbot:Clean(gameCamera:GetPropertyChangedSignal('ViewportSize'):Connect(function()
				UpdateCircle()
			end))

			local owlTagCache, owlTagAt = nil, 0
			local function getOwlTags()
				local now = tick()
				if not owlTagCache or now - owlTagAt > 0.5 then
					owlTagCache = collectionService:GetTagged('Owl')
					owlTagAt = now
				end
				return owlTagCache
			end

			local function AimLaunchValues(native, self, LaunchData, WorldMeta, Origin, ShootPosition)
				if type(native) ~= 'table' then return end

				local LaunchPosition = ShootPosition
				if typeof(LaunchPosition) ~= 'Vector3' then
					local ok, res = pcall(self.getLaunchPosition, self, Origin)
					if not (ok and typeof(res) == 'Vector3') then
						res = nil
					end
					if typeof(res) ~= 'Vector3' and entitylib.isAlive then
						res = entitylib.character.RootPart.Position + Vector3.new(0, 2, 0)
					end
					LaunchPosition = res
				end
				if typeof(LaunchPosition) ~= 'Vector3' then
					return nil
				end

				local ProjectileName = tostring(LaunchData.projectile or '')
				if ProjectileName:find('splash_potion', 1, true) then
					if not Potions.Enabled then
						return nil
					end
				elseif not OtherProjectiles.Enabled and not ProjectileName:find('arrow', 1, true) and not (UseUmeko.Enabled and ProjectileName:find('^ninja_chakram')) then
					return nil
				end

				local BlacklistName = (ProjectileName == 'glue_trap' or ProjectileName == 'glue_projectile') and 'gloop' or ProjectileName
				if table.find(Blacklist.ListEnabled or {}, BlacklistName) then
					return nil
				end

				local metaOk, metaRes = pcall(LaunchData.getProjectileMeta, LaunchData)
				local ProjectileMeta = metaOk and type(metaRes) == 'table' and metaRes or (bedwars.ProjectileMeta and bedwars.ProjectileMeta[ProjectileName])
				if not ProjectileMeta then
					return nil
				end

				local Lifetime = WorldMeta and (ProjectileMeta.predictionLifetimeSec or ProjectileMeta.lifetimeSec or 3) or (ProjectileMeta.lifetimeSec or 3)
				local Gravity = (native and tonumber(native.gravitationalAcceleration)) or ((tonumber(ProjectileMeta.gravitationalAcceleration) or 196.2) * (tonumber(LaunchData.gravityMultiplier) or 1))
				if Gravity < 1 then
					Gravity = 0
				end

				local Tool = store.hand and store.hand.tool
				local ToolMeta = Tool and bedwars.ItemMeta and bedwars.ItemMeta[Tool.Name]
				local SourceMeta = ToolMeta and ToolMeta.projectileSource
				local BaseSpeed = tonumber(ProjectileMeta.launchVelocity) or 100
				local NativeSpeed = native and typeof(native.initialVelocity) == 'Vector3' and native.initialVelocity.Magnitude or 0
				local NativeDraw = (native and tonumber(native.drawDurationSeconds)) or tonumber(LaunchData.drawDurationSeconds) or 0

				-- Bows scale with how long they were drawn. Crossbows and the other fixed-charge
				-- launchers (multiShotChargeTime plus a reload) have no strength charge, so handing
				-- the server a made-up draw and speed gets the arrow eaten. Keep every native value
				-- for those and only replace where we aim.
				local StrengthCharge = tonumber(SourceMeta and SourceMeta.maxStrengthChargeSec)
					or tonumber(SourceMeta and SourceMeta.maxDrawDurationSeconds)

				local ProjectileSpeed, DrawDuration
				if not StrengthCharge then
					if NativeSpeed <= 0 then
						return nil
					end
					ProjectileSpeed, DrawDuration = NativeSpeed, NativeDraw
				elseif AutoCharge.Enabled or not Aim.Enabled then
					ProjectileSpeed, DrawDuration = BaseSpeed, StrengthCharge
				else
					local MinScalar = tonumber(SourceMeta and SourceMeta.minStrengthScalar) or 1
					if NativeSpeed > 0 then
						ProjectileSpeed = NativeSpeed
					else
						local DrawPct = StrengthCharge > 0 and math.clamp(NativeDraw / StrengthCharge, 0, 1) or 0
						ProjectileSpeed = BaseSpeed * (MinScalar + (1 - MinScalar) * DrawPct)
					end
					DrawDuration = NativeDraw
				end
				if not ProjectileSpeed or ProjectileSpeed <= 0 then
					return nil
				end

				local SpawnOffset = ProjectileName == 'owl_projectile' and Vector3.zero or (typeof(LaunchData.fromPositionOffset) == 'Vector3' and LaunchData.fromPositionOffset or Vector3.zero)
				local OffsetPosition = (native and typeof(native.positionFrom) == 'Vector3' and native.positionFrom) or (LaunchPosition + SpawnOffset)

				local BowConstants = bedwars.BowConstantsTable or {}
				local Relative = SourceMeta and SourceMeta.relativeOverride
				local RelX, RelY, RelZ = BowConstants.RelX or 0.8, BowConstants.RelY or -0.6, BowConstants.RelZ or 0
				if type(Relative) == 'table' then
					RelX, RelY, RelZ = Relative.relX or 0, Relative.relY or 0, Relative.relZ or 0
				end

				local map = workspace:FindFirstChild('Map')
				if map then
					ArcCheck.FilterDescendantsInstances = {map}
				end

				local PartName = PartOption.Value == 'Dynamic' and (IsHeadshotProjectile(Tool and Tool.Name) and 'Head' or 'RootPart') or PartOption.Value

				local function GetLaunchValues(Ent)
					if not Ent.Character or not Ent.RootPart then
						return nil
					end

					local Balloons = Ent.Character:GetAttribute('InflatedBalloons')
					local PlayerGravity = workspace.Gravity

					if Balloons and Balloons > 0 then
						PlayerGravity = balloonGravity(Balloons, Ent.Character)
					end

					if Ent.Character.PrimaryPart and Ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
						PlayerGravity = 6
					end

					if Ent.Player and Ent.Player:GetAttribute('IsOwlTarget') then
						for _, v in getOwlTags() do
							if v:GetAttribute('Target') == Ent.Player.UserId and v:GetAttribute('Status') == 2 then
								PlayerGravity = 0
								break
							end
						end
					end

					local AimPart = GetTargetPart(Ent, PartName)
					local Velocity = ProjectileName == 'telepearl' and Vector3.zero or AimPart.AssemblyLinearVelocity
					if Horizontal.Value ~= 1 or Vertical.Value ~= 1 then
						Velocity = Vector3.new(Velocity.X * Horizontal.Value, Velocity.Y * Vertical.Value, Velocity.Z * Horizontal.Value)
					end
					local EntRootVelocity = Ent.RootPart.AssemblyLinearVelocity
					local Airborne = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(EntRootVelocity.Y) > 0.01
					local JumpVelocity = Ent.Jumping and 42.6 or nil
					local AimTarget = AimPart.Position

					-- The game spawns the projectile at the hand offset from positionFrom, not at
					-- positionFrom itself. Solve, move the origin to the real spawn point, re-solve,
					-- and shift the result back so the returned direction accounts for the offset.
					local calc, flight
					calc, _, flight = prediction.SolveTrajectory(
						OffsetPosition, ProjectileSpeed, Gravity,
						AimTarget, Velocity,
						PlayerGravity, Ent.HipHeight, JumpVelocity,
						ArcCheck, Airborne,
						Ent.RootPart.Position, Ent.RootPart,
						nil, true
					)
					for _ = 1, 2 do
						if not calc or not flight then break end
						local Spawn = prediction.GetSpawnPosition(OffsetPosition, calc, RelX, RelY, RelZ)
						local corrected, _, correctedTime = prediction.SolveTrajectory(
							Spawn, ProjectileSpeed, Gravity,
							AimTarget, Velocity,
							PlayerGravity, Ent.HipHeight, JumpVelocity,
							ArcCheck, Airborne,
							Ent.RootPart.Position, Ent.RootPart,
							nil, true
						)
						if not corrected or not correctedTime then break end
						calc = OffsetPosition + (corrected - Spawn)
						flight = correctedTime
					end

					if not calc or not flight or flight > Lifetime then
						return nil
					end

					local values = table.clone(native)
					values.initialVelocity = CFrame.lookAt(OffsetPosition, calc).LookVector * ProjectileSpeed
					values.drawDurationSeconds = DrawDuration
					return values
				end

				local Values, Attempts = nil, 0
				local Ent = entitylib.EntityMouse({
					Part = 'RootPart',
					Range = FOV.Value,
					Players = Targets.Players.Enabled,
					NPCs = Targets.NPCs and Targets.NPCs.Enabled or false,
					Wallcheck = Targets.Walls.Enabled or nil,
					Origin = entitylib.isAlive and (ShootPosition or entitylib.character.RootPart.Position) or Vector3.zero,
					MouseOrigin = GetMouseOrigin(),
					Sort = sortmethods[Sort.Value],
					Check = function(Candidate)
						if MiloCheck.Enabled and IsDisguised(Candidate) then
							return false
						end
						if (Candidate.RootPart.Position - entitylib.character.RootPart.Position).Magnitude > Distance.Value then
							return false
						end
						if Attempts >= 24 then
							return false
						end
						Attempts += 1
						Values = GetLaunchValues(Candidate)
						return Values ~= nil
					end
				})

				if Ent and Values then
					if targetinfo and targetinfo.Targets then
						targetinfo.Targets[Ent] = tick() + 1
					end
					return Values
				end
			end

			local hookErrorAt = 0
			Hook = function(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
				local native = Old(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
				if ProjectileAimbot.Enabled and not (vape.Modules.SilentAim and vape.Modules.SilentAim.Enabled) then
					local Success, Values = pcall(AimLaunchValues, native, self, LaunchData, WorldMeta, Origin, ShootPosition)
					if Success and Values then
						paLog('launch', 'launch values aimed: ' .. tostring(LaunchData and LaunchData.projectile))
						return Values
					end
					if not Success and (tick() - hookErrorAt) >= 3 then
						hookErrorAt = tick()
						warn('[ProjectileAimbot] ' .. tostring(Values))
					end
				end
				return native
			end

			-- A profile can enable this while bedwars is still loading, so keep trying for the
			-- controller instead of turning the module off on the first miss.
			local function installHook()
				local controller = bedwars.ProjectileController
				if not controller or type(controller.calculateImportantLaunchValues) ~= 'function' then
					return false
				end
				if controller.calculateImportantLaunchValues ~= Hook then
					Old = controller.calculateImportantLaunchValues
					controller.calculateImportantLaunchValues = Hook
				end
				return true
			end

			if not installHook() then
				task.spawn(function()
					local deadline = tick() + 20
					repeat
						task.wait(0.25)
						vape.Libraries.projectileaim.Install()
					until not ProjectileAimbot.Enabled or installHook() or tick() > deadline
				end)
			end
			-- The packet path works on its own; the launch hook only refines it when present.
			vape.Libraries.projectileaim.Install()
			if PADebug and PADebug.Enabled then
				task.delay(0.5, function()
					local text = 'launch ' .. tostring(Hook ~= nil)
						.. ' | packet ' .. tostring(vape.Libraries.projectileaim.Namecall ~= nil)
						.. ' | local ' .. tostring(vape.Libraries.projectileaim.Local ~= nil)
					paLog('install', text)
					-- The loader clears the console and notif() is a stub, so the GUI notification
					-- pane is the only channel that actually reaches the player.
					pcall(function() vape:CreateNotification('ProjectileAimbot', text, 8) end)
				end)
			end
		end,
		Tooltip = 'Silently adjusts your aim towards the enemy'
	})

	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})

	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = getSortList({'Distance'}),
		Default = 'Distance'
	})

	PartOption = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic'},
		Default = 'RootPart',
		Tooltip = 'Dynamic aims at the head with headshot-capable bows, including tactical bows and Archer, and at the body with everything else'
	})

	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Function = function(Val)
			if CircleObject then
				CircleObject.Radius = Val
			end
		end
	})

	Distance = ProjectileAimbot:CreateSlider({
		Name = 'Distance',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Suffix = 'studs',
		Tooltip = 'Maximum enemy distance from you'
	})

	PADebug = ProjectileAimbot:CreateToggle({
		Name = 'Debug',
		Tooltip = 'Prints to the console which projectile layer aimed a shot (local projectile, launch values, or packet)'
	})

	ProjectileAimbot:CreateToggle({
		Name = 'Range Circle',
		Function = function(Callback)
			if Callback then
				local ok, circle = pcall(function()
					if not Drawing then return nil end
					return Drawing.new('Circle')
				end)
				if ok and circle then
					CircleObject = circle
					CircleObject.Filled = CircleFilled.Enabled
					CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
					CircleObject.Position = GetMouseOrigin()
					CircleObject.Radius = FOV.Value
					CircleObject.NumSides = 100
					CircleObject.Thickness = CircleThickness.Value
					CircleObject.Transparency = 1 - CircleTransparency.Value
					CircleObject.Visible = ProjectileAimbot.Enabled
				end
			elseif CircleObject then
				pcall(function()
					CircleObject.Visible = false
					CircleObject:Remove()
				end)
				CircleObject = nil
			end

			CircleColor.Object.Visible = Callback
			CircleTransparency.Object.Visible = Callback
			CircleThickness.Object.Visible = Callback
			CircleFilled.Object.Visible = Callback
		end
	})

	CircleColor = ProjectileAimbot:CreateColorSlider({
		Name = 'Circle Color',
		Function = function(Hue, Sat, Val)
			if CircleObject then
				CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
			end
		end,
		Darker = true,
		Visible = false
	})

	CircleTransparency = ProjectileAimbot:CreateSlider({
		Name = 'Transparency',
		Min = 0,
		Max = 1,
		Decimal = 10,
		Default = 0.5,
		Function = function(Val)
			if CircleObject then
				CircleObject.Transparency = 1 - Val
			end
		end,
		Darker = true,
		Visible = false
	})

	CircleThickness = ProjectileAimbot:CreateSlider({
		Name = 'Thickness',
		Min = 1,
		Max = 10,
		Decimal = 10,
		Default = 1,
		Function = function(Val)
			if CircleObject then
				CircleObject.Thickness = Val
			end
		end,
		Darker = true,
		Visible = false,
		Tooltip = "How wide the circle's outline is, has no effect while Circle Filled is on"
	})

	CircleFilled = ProjectileAimbot:CreateToggle({
		Name = 'Circle Filled',
		Function = function(Callback)
			if CircleObject then
				CircleObject.Filled = Callback
			end
		end,
		Darker = true,
		Visible = false
	})

	Horizontal = ProjectileAimbot:CreateSlider({
		Name = 'Horizontal prediction',
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 100,
		Tooltip = 'Scales how far ahead of the target you aim sideways'
	})

	Vertical = ProjectileAimbot:CreateSlider({
		Name = 'Vertical prediction',
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 100,
		Tooltip = 'Scales how far ahead of the target you aim while it rises or falls'
	})

	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = 'Auto Charge',
		Function = function(Callback)
			if Aim and Aim.Object then
				Aim.Object.Visible = Callback
			end
		end,
		Default = true,
		Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage'
	})

	Aim = ProjectileAimbot:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Changes your trajectory to match charge percentage.'
	})

	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true,
		Tooltip = 'Aims everything that is not an arrow or a splash potion'
	})

	UseUmeko = ProjectileAimbot:CreateToggle({
		Name = 'Use umeko',
		Tooltip = "Aims umeko's chakram even with Other Projectiles off"
	})

	Potions = ProjectileAimbot:CreateToggle({
		Name = 'Shoot pots',
		Default = true,
		Tooltip = 'Aims heal, poison and sleep splash potions, separate from Other Projectiles'
	})

	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})

	MiloCheck = ProjectileAimbot:CreateToggle({
		Name = 'Milo check',
		Default = true,
		Tooltip = 'Skips Milo players while they are disguised as a block'
	})
end)

run(function()
	local ProjectileHitbox
	local Targets
	local Expand
	local Visible
	local objects = {}

	local hitboxSize = Vector3.new(3, 6, 3)
	local hitboxColor = Color3.fromRGB(255, 60, 180)

	local function updateSize(val)
		hitboxSize = Vector3.new(3, 6, 3) + Vector3.one * ((val or 0) / 5)
		for _, part in pairs(objects) do
			part.Size = hitboxSize
		end
	end

	local function holdingProjectile()
		local live = liveHandTool()
		if live then return isProjectileTool(live) end
		local hand = store.hand
		return hand ~= nil and isProjectileTool(hand.tool)
	end

	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude

	local function behindWall(ent)
		if not Targets or not Targets.Walls or not Targets.Walls.Enabled then return false end
		if not ent.RootPart then return false end
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return false end
		local origin = entitylib.character.RootPart.Position
		local direction = ent.RootPart.Position - origin
		rayParams.FilterDescendantsInstances = {entitylib.character, ent.Character}
		local result = workspace:Raycast(origin, direction, rayParams)
		return result ~= nil and (result.Position - origin).Magnitude < direction.Magnitude - 0.5
	end

	local function wanted(ent)
		if not ent.Targetable or not ent.Character or not ent.RootPart then return false end
		if not Targets then return false end
		if ent.Player then
			return Targets.Players ~= nil and Targets.Players.Enabled == true
		end
		return Targets.NPCs ~= nil and Targets.NPCs.Enabled == true
	end

	local function create(ent)
		if objects[ent] then return end
		if not wanted(ent) then return end
		if behindWall(ent) then return end
		local part = Instance.new('Part')
		part.Name = 'ProjectileHitbox'
		part.Archivable = false
		part.Size = hitboxSize
		part.CFrame = ent.RootPart.CFrame
		part.CanCollide = false
		part.CanTouch = false
		part.Massless = true
		part.Color = hitboxColor
		part.Material = Enum.Material.Neon
		part.Transparency = (Visible and Visible.Enabled) and 0.55 or 1
		part.LocalTransparencyModifier = (Visible and Visible.Enabled) and 0 or 1
		part.Parent = ent.Character
		local weld = Instance.new('Motor6D')
		weld.Part0 = ent.RootPart
		weld.Part1 = part
		weld.Parent = part
		objects[ent] = part
	end

	local function clear()
		for _, part in pairs(objects) do
			part:Destroy()
		end
		table.clear(objects)
		for _, plr in playersService:GetPlayers() do
			local char = plr.Character
			if char then
				for _, old in char:GetChildren() do
					if old.Name == 'ProjectileHitbox' then old:Destroy() end
				end
			end
		end
		for _, ent in entitylib.List do
			local char = ent.Character
			if char then
				for _, old in char:GetChildren() do
					if old.Name == 'ProjectileHitbox' then old:Destroy() end
				end
			end
		end
	end

	ProjectileHitbox = vape.Categories.Blatant:CreateModule({
		Name = 'Projectile Hitbox',
		Function = function(callback)
			if callback then
				if Expand then updateSize(Expand.Value) end
				local frame = 0
				ProjectileHitbox:Clean(runService.Heartbeat:Connect(function()
					frame = frame + 1
					if frame % 3 ~= 0 then return end
					if not holdingProjectile() then
						if next(objects) ~= nil then clear() end
						return
					end
					for ent, part in pairs(objects) do
						if not ent.Character or not ent.Character.Parent or not ent.RootPart then
							part:Destroy()
							objects[ent] = nil
						else
							part.Size = hitboxSize
						end
					end
					local list = entitylib.List
					for i = 1, #list do
						create(list[i])
					end
				end))
			else
				clear()
			end
		end,
		Tooltip = 'expands enemy hitboxes while a projectile is in hand'
	})

	Targets = ProjectileHitbox:CreateTargets({
		Players = true,
		NPCs = false,
		Walls = false
	})

	Expand = ProjectileHitbox:CreateSlider({
		Name = 'Expand amount',
		Min = 0,
		Max = 20,
		Default = 6,
		Decimal = 10,
		Function = function(val)
			updateSize(val)
		end,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})

	Visible = ProjectileHitbox:CreateToggle({
		Name = 'Visible',
		Default = true,
		Function = function(callback)
			local transparency = callback and 0.55 or 1
			local localMod = callback and 0 or 1
			for _, part in pairs(objects) do
				part.Transparency = transparency
				part.LocalTransparencyModifier = localMod
			end
		end
	})
end)

local Attacking
run(function()
	local Killaura
	local Targets
	local Sort
	local SwingRange
	local AttackRange
	local AngleSlider
	local Swing
	local Animation
	local AnimationMode
	local AnimationSpeed
	local AnimationTween
	local Limit
	local LegitAura
	local AttackCheck
	local kitChecks
	local SwingTime
	local SwingTimeSlider
	local AirHit
	local AirHitsChance
	local FastHits
	local LegitSwitch
	local Arrows
	local Gloops
	local GloopCooldown
	local Fireballs
	local FireballCooldown
	local FireRate
	local ArrowCharge = 100 -- Default 100% charge (full power)
	local UseKits
	local AttackRemote
	local HitregMode
	local DynamicDelaySlider
	local lastAttackTime = 0
	local lastTargetTime = 0
	local lastAnimTime = 0 -- Track when last animation was played to prevent doubling
	local lastSwingAnim = 0 -- Gate for the real sword swing so it runs at the sword's own speed
	local anims, AnimDelay, AnimTween, armC0 = vape.Libraries.auraanims, tick()
	local FROZEN_THRESHOLD = 10
	local HIT_PERIOD = 0.296 -- fallback only; the real period comes from SwordTiming.resolvePeriod
	local SERVER_FLOOR = 0.292
	local SERVER_REACH = 14.399
	local NORMAL_SWORD_SWING_SPEED = 0.35 -- Standard in-game sword swing speed, NEVER changes
	local AURA_SWING_INTERVAL = 0.35 -- cosmetic only: matches the native sword swing; hits keep their own cadence
	local kaPeriod = HIT_PERIOD
	local animPeriod = NORMAL_SWORD_SWING_SPEED -- Animation is ALWAYS decoupled from hit timing
	local kaLastSrv = 0 -- scheduled server time of the last accepted hit
	local _kaPingScale, _kaPingAt = 1, 0
	local function kaPingScale()
		local now = tick()
		if now - _kaPingAt >= 0.5 then
			_kaPingAt = now
			local p = netPing()
			_kaPingScale = 1 + math.clamp((p - 0.12) * 0.4, 0, 0.12)
		end
		return _kaPingScale
	end
	local lastProjectileTime = 0 -- Track when last projectile was fired
	local glueRemote = {InvokeServer = function() end}
	local projectileRemote = {InvokeServer = function() end}
	local gloopTracker = {}
	local fireballTracker = {}

	-- DYNAMIC SWORD TIMING & HITSPACING SYSTEM
	local SwordTiming = {
		SafeSpacing  = 0.295, -- Stealth Mode delay
		HighSpacing  = 0.2855, -- spacing used by the Dynamic/Advanced calculation
		HitFloor     = 0.292, -- the server's minimum allowed time between hits. Going below this will cause ghost hits.
		GapFloor     = 0.2945, -- minimum gap between con hits
		ArrivalFloor = 0.274, -- how early it can arrive b4 ghosting 
		CooldownCorrection = (0.017999999225139618 / 10) + 0.013412,
	}

	local WeaponSpacing = {
		[0.21] = 0.229,
		[0.25] = 0.249,
		[0.35] = 0.345,
		[0.4]  = 0.341,
		[0.6]  = 0.63,
	}

	-- HighMode: 'Stealth Mode' | 'Advanced Mode' | 'Dynamic'
	-- DynamicDelay: slider value (1-100) only used when HighMode == 'Dynamic'
	function SwordTiming.Calculate(Speed, HighMode, DynamicDelay, Budget, Hits)
		local Stock = Speed == 0.3
		local Normal = (HighMode == 'Advanced Mode' or HighMode == 'Dynamic') and SwordTiming.HighSpacing or SwordTiming.SafeSpacing
		local Spacing = Stock and Normal or WeaponSpacing[Speed] or Speed + 0.03

		if HighMode == 'Dynamic' and DynamicDelay then
			Spacing = math.max(Spacing * (DynamicDelay / 100), Budget or 0)
		end

		if Hits and Hits ~= 35 then Spacing = math.max(Spacing, 10 / math.max(Hits - 1, 1)) end
		Spacing = math.max(Spacing, Budget or 0)
		local Scale = Spacing / (Stock and Normal or SwordTiming.SafeSpacing)
		local Gap = (Scale < 1 and SwordTiming.GapFloor or SwordTiming.HitFloor) * Scale
		if Stock and (HighMode == 'Advanced Mode' or HighMode == 'Dynamic') then
			Gap = math.max(Gap, SwordTiming.GapFloor, Budget or 0)
		end
		return Spacing, Scale, Gap, math.max(Speed - SwordTiming.CooldownCorrection, 0), Stock
	end

	-- 240Hz Quantized Clock
	local preciseRemainder = 0
	local preciseTimestamp = tick()

	task.spawn(function()
		glueRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)

	task.spawn(function()
		task.wait()
		local _remotes = getgenv().remotes or remotes
		projectileRemote = bedwars.Client:Get(_remotes.FireProjectile).instance
		pcall(function()
			AttackRemote = bedwars.Client:Get(_remotes.AttackEntity).instance
		end)
	end)

	local function getKnitControllers()
		return (bedwars.KnitClient and bedwars.KnitClient.Controllers) or (bedwars.Knit and bedwars.Knit.Controllers)
	end

	local function quantize240(value)
		return math.ceil(value / (1 / 240)) * (1 / 240)
	end

	local function updatePreciseClock()
		local now = tick()
		if now - preciseTimestamp >= 0.25 then
			preciseRemainder = 0
			preciseTimestamp = now
		end
		local elapsed = now - preciseTimestamp
		local steps = math.floor(elapsed / (1 / 240))
		preciseRemainder = math.max(preciseRemainder, steps * (1 / 240))
		return preciseRemainder
	end

	-- The server, not the client, caps how often a hit lands. Retrying faster than that cap costs
	-- nothing and makes a late frame harmless, while a gap that lands just outside a window costs a
	-- whole period. This is the Stealth/Dynamic mapping the consistent build used.
	function SwordTiming.resolvePeriod(meta)
		local mode = (HitregMode and HitregMode.Value) or 'Stealth Mode'
		local speed = (meta and meta.sword and meta.sword.attackSpeed) or 0.3
		local delay
		if mode == 'Dynamic' then
			delay = (DynamicDelaySlider and DynamicDelaySlider.Value) or 100
		elseif mode == 'Advanced Mode' then
			delay = 49.55
		else
			delay = 50
		end
		return quantize240(SwordTiming.Calculate(speed, 'Dynamic', delay, 0, 35))
	end

